def nfaq(n):
    nm=n['name'];Q=[]
    for r in n['rules']:
        QT={'Licensing':'Do I need a licence to run a short-term let in {nm}?','Planning / control areas':'Do I need planning permission for a short-term let in {nm}?','Visitor levy':'Is there a visitor levy (tourist tax) on short-term lets in {nm}?','Tax (FHL)':'How are holiday lets taxed in {nm} now the FHL regime has ended?','Tax (FHL abolished)':'How are holiday lets taxed in {nm} now the FHL regime has ended?','Non-domestic rates thresholds':'When does a short-term let in {nm} pay business rates instead of council tax?','Registration scheme':'Is there a short-term let registration scheme in {nm}?','Planning use class (C5)':'Is there a new planning use class (C5) for short-term lets in {nm}?','London 90-night rule':'What is the London 90-night rule?','Business rates vs council tax':'When does a holiday let in {nm} pay business rates instead of council tax?','Overnight Visitor Levy':'Is {nm} bringing in an Overnight Visitor Levy?','Safety':'What safety rules apply to holiday lets in {nm}?','Registration (WRA)':'Do I need to register my holiday let with the Welsh Revenue Authority?','182-day rule (rates)':'What is the 182-day rule for holiday lets in {nm}?','182-day rule consultation':'Is the 182-day rule in {nm} changing?','Planning':'Do I need planning permission for a short-term let in {nm}?','Certification':'Do I need a Tourism NI certificate to let my property in {nm}?','Rates':'Does a holiday let in {nm} pay business rates?'}
        t=r['topic'];q=QT.get(t,f'What are the rules on {t} for short-term lets in {{nm}}?').format(nm=nm)
        Q.append((q,f'{r["status"]}. {r["text"]}'))
    ld=json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in Q]}).replace('</','<\\/')
    h=f'<h2>{nm} short-let rules: quick answers</h2>'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in Q)+'<p class="small">Answers summarise the table above. Follow each row\'s official source before acting.</p>'
    return h,f'<script type="application/ld+json">{ld}</script>'

