# ---- Aberdeenshire, Dumfries and Galloway (sources fetched 22 Oct 2026) ----
AB='https://www.aberdeenshire.gov.uk/licensing/licences-and-permits/stl-apply-or-renew'
AB0='https://aberdeenshire.gov.uk/licensing/licences-and-permits/short-term-let-licensing/'
