CX.update({
'south-ayrshire':dict(lic=(SC_LIC[0]+' <a href="'+SAY+'" rel="nofollow">Apply online through South Ayrshire Council</a> and pay at the end. Send everything on the council\'s checklist with the application (incomplete ones are rejected and the fee is not refunded): a scaled floor plan, a video of the property, the Scottish Fire and Rescue checklist, a legionella risk assessment and a planning operational statement. You then display a site notice at or near the property for 21 days from the date you applied and send a certificate of compliance. Renewals must go in before your licence expires.',SC_LIC[1]+[SAY,SAYP]),
 ctrl=(NOCA[0]+' South Ayrshire asks every applicant for a planning operational statement, so its planning team can decide during the consultation whether your let needs planning permission.',NOCA[1]+[SAY]),
 levy=('No levy. A report to the council\'s Cabinet on 17 June 2025 recommended pausing all work on a visitor levy until August 2027, after a survey in which 79% of 502 responses opposed one. Even if it is revived then, the council would need to publish a scheme, consult on it and give at least 18 months\' notice before charging. (We have seen the report\'s recommendation but not a record of the Cabinet vote, so treat the pause as reported, not confirmed.)',['https://www.south-ayrshire.gov.uk/article/80918/Future-of-proposed-Visitor-Levy-in-South-Ayrshire','https://www.south-ayrshire.gov.uk/media/15276/Visitor-Levy-Scheme/pdf/item_9a_20250617_C_Visitor_Levy_beyeswk2q9ik.pdf?m=1749210282673']),
 fees=('New licence: secondary letting £300 (up to 4 guests) / £480 (5 or more); home sharing or home letting (or both) £150 / £300. Renewal: secondary £240 / £420; home sharing or letting £90 / £240. Temporary licence £120, variation £90, replacement licence £60. Fees are non-refundable. These are the fees in the council\'s August 2024 policy and on its scheme page. The council consulted on a revised policy, including an updated fee structure, until 12 June 2026, so check for new fees before you apply. (south-ayrshire.gov.uk blocked our direct check; read via a search index of the official pages on 24 Oct 2026.)',[SAY,SAYP]),
 dates=['17 Jun 2025: Cabinet report recommends pausing levy work','12 Jun 2026: licensing policy and fee review consultation closed','Aug 2027: earliest the levy would be looked at again']),
'angus':dict(lic=(SC_LIC[0]+' Apply through <a href="'+ANG+'" rel="nofollow">Angus Council\'s short-term lets pages</a>. A new licence lasts up to 3 years and a renewal up to 6 years. If you started letting after 1 Oct 2022 you cannot trade until licensed, and the council has 9 months to decide. A temporary licence lasts up to 6 weeks, and you can get up to three temporary exemptions totalling no more than 6 weeks in 12 months. The council keeps a public register of short-term lets.',SC_LIC[1]+[ANG+'?page_id=1844',ANG+'?page_id=1845']),
 ctrl=(NOCA[0]+' Angus Council confirms there are currently no short-term let control areas in Angus, and says that could change.',NOCA[1]+[ANG+'?page_id=1851']),
 levy=('No levy. In June 2024 the Policy and Resources Committee said it was not making any decision to introduce a levy and asked officers to engage with stakeholders first. In October 2025 the council set aside £50,000 of UK Shared Prosperity funding for a tourism framework and early engagement on a possible levy. There is no published scheme or consultation yet, and any Scottish levy needs at least 18 months\' notice.',['https://www.angus.gov.uk/sites/default/files/2024-05/Report%20170_24%20Consideration%20of%20the%20Introduction%20of%20a%20Local%20Visitor%20Levy.pdf','https://www.angus.gov.uk/sites/default/files/2025-09/Report%20289_25_UK%20Shared%20Prosperity%20Fund%202025-26%20Funding%20Update%20and%20Allocations.pdf']),
 fees=('Same fee for all licence types, set by guest numbers: £349 (1 to 5 guests), £460 (6 to 20), £588 (more than 20) for a new 3-year licence or a 6-year renewal. Provisional licence 20% of the full fee (£69.80 / £92 / £117.60), confirmation 80% (£279.20 / £368 / £470.40). Temporary licence or temporary exemption £174.50, variation £75, transfer £75, duplicate £20. No refund if refused or granted for a shorter period. The April 2026 licensing fee rise did not cover short-term lets, so these still apply.',[ANG+'?page_id=1846','https://www.angus.gov.uk/sites/default/files/2026-03/Report%20107_26%20Review%20of%20Fees.pdf']),
 dates=['4 Jun 2024: committee asks for stakeholder engagement on a levy (no decision)','14 Nov 2024: updated licensing policy considered','Oct 2025: £50,000 set aside for early levy engagement']),
})
# ---- North Ayrshire (sources fetched 24 Oct 2026) ----
NAY='https://www.north-ayrshire.gov.uk/business-licensing/licensing/accommodation-licences'
NAYP='https://www.north-ayrshire.gov.uk/documents/short-term-let-licensing-policy'
CX.update({
'north-ayrshire':dict(lic=(SC_LIC[0]+' Apply to <a href="'+NAY+'" rel="nofollow">North Ayrshire Council\'s licensing team</a>, using its STL licensing checklist to gather your supporting documents, and include the fee. A licence lasts 3 years from the date of issue and is normally renewed for a further 3 years. If you apply to renew before it expires, your licence carries on until the council decides. Processing can take up to 3 months. Where public notification is needed, a site notice is normally displayed for 21 days. This covers the mainland and the islands of Arran and Cumbrae.',SC_LIC[1]+[NAY,NAYP]),
 ctrl=(NOCA[0]+' North Ayrshire\'s licensing policy confirms the council does not currently have a short-term let control area and has not adopted an overprovision approach. You may still need planning permission, depending on the property.',NOCA[1]+[NAYP]),
 levy=('No levy yet. North Ayrshire\'s 2025 Visitor Management Plan says officers are looking at a possible visitor levy, including stakeholder pre-consultation and an options appraisal, with a report to Cabinet to follow. In January 2026 the Scottish Government said the council had not yet confirmed whether it will go ahead. There is no published scheme, and any Scottish levy needs at least 18 months\' notice. Separately, second homes in North Ayrshire (including on Arran and Cumbrae) have paid a 100% council tax premium (double council tax) since 1 April 2025; a let that qualifies for business rates is not charged council tax.',['https://north-ayrshire.cmis.uk.com/north-ayrshire/Document.ashx?czJKcaeAi5tUFL1DTL2UE4zNRBcoShgo=yjfa8npxsHO7tKbtvX6Ji80pJxePKDYY%2BU9pxstDRxUOF0P%2Bxu8%2BiQ%3D%3D','https://www.gov.scot/publications/visitor-levy-amendment-scotland-bill-island-communities-impact-assessment-icia/','https://www.north-ayrshire.gov.uk/news/council-tax-levy-to-be-implemented-on-second-homes']),
 fees=('Fees from 1 April 2026, by maximum occupancy (up to 4 guests / 5 or more). New licence: secondary let £300 / £480; home sharing or home letting (or both) £150 / £300. Renewal: secondary let £240 / £420; home sharing or letting £135 / £240. Provisional licence: 25% of the new fee when you apply, 75% on confirmation. Temporary licence: 50% of the new fee. Amendment £75, variation £90, transfer £110, replacement licence £60. No refund if refused, withdrawn or granted for a shorter period.',[NAY]),
 dates=['12 Feb 2025: council approves 100% second homes council tax premium','1 Apr 2025: second homes premium starts','1 Apr 2026: current licence fees apply','Jan 2026: Scottish Government says levy decision not yet confirmed']),
})
